                    </div>
                </form>
            </div>
        </div>

        <!-- Plant Details Modal -->
        <div id="plantDetailsModal" class="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 hidden">
            <div class="bg-white rounded-lg p-6 w-full max-w-md">
                <div class="flex justify-between items-center mb-4">
                    <h2 id="detailsPlantName" class="text-xl font-bold text-gray-800">Plant Details</h2>
                    <button id="closeDetailsBtn" class="text-gray-500 hover:text-gray-700">
                        <i class="fas fa-times"></i>
                    </button>
                </div>
                <div class="mb-4">
                    <div class="flex items-center mb-3">
                        <img id="detailsPlantImage" src="" alt="Plant" class="w-16 h-16 rounded-full object-cover mr-4">
                        <div>
                            <h3 id="detailsPlantName" class="font-bold text-lg"></h3>
                            <p id="detailsPlantType" class="text-gray-600"></p>
                        </div>
                    </div>
                    <div class="grid grid-cols-2 gap-4 mb-4">
                        <div class="bg-gray-50 p-3 rounded-lg">
                            <p class="text-sm text-gray-500">Water Frequency</p>
                            <p id="detailsWaterFrequency" class="font-medium"></p>
                        </div>
                        <div class="bg-gray-50 p-3 rounded-lg">
                            <p class="text-sm text-gray-500">Last Watered</p>
                            <p id="detailsLastWatered" class="font-medium"></p>
                        </div>
                        <div class="bg-gray-50 p-3 rounded-lg">
                            <p class="text-sm text-gray-500">Next Watering</p>
                            <p id="detailsNextWatering" class="font-medium"></p>
                        </div>
                        <div class="bg-gray-50 p-3 rounded-lg">
                            <p class="text-sm text-gray-500">Water Urgency</p>
                            <p id="detailsWaterUrgency" class="font-medium"></p>
                        </div>
                    </div>
                    <div class="flex justify-between">
                        <button id="waterPlantBtn" class="bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center">
                            <i class="fas fa-tint mr-2"></i> Water Plant
                        </button>
                        <button id="deletePlantBtn" class="bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg flex items-center">
                            <i class="fas fa-trash mr-2"></i> Delete
                        </button>
                    </div>
                </div>
            </div>
        </div>

        <!-- Notification Toast -->
        <div id="notification" class="fixed bottom-4 right-4 bg-green-500 text-white px-4 py-2 rounded-lg shadow-lg transform translate-y-20 opacity-0 transition-all duration-300 flex items-center">
            <i class="fas fa-check-circle mr-2"></i>
            <span id="notificationText"></span>
        </div>
    </div>

    <script>
