Here's a **self-contained, single-page webapp for Urban Mushroom Foraging** (a hyper-specific, useful niche) using Tailwind CSS. It includes interactive ID assistance, localStorage-powered foraging logs, dark mode, and responsive design—*all in one HTML file*.

```html
<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Urban Mushroom Forager | Log & ID</title>
    <!-- Inline Tailwind Config (Custom Niche Colors) -->
    <script>
        tailwind.config = {
            darkMode: 'class',
            theme: {
                extend: {
                    colors: {
                        moss: '#8B9A46',
                        earth: '#5C4033',
                        cream: '#FFF8E1',
                        toxicRed: '#D32F2F',
                        edibleGreen: '#388E3C',
                        unknownGray: '#757575'
                    },
                    fontFamily: {
                        sans: ['Inter', 'system-ui', 'sans-serif'],
                        serif: ['Georgia', 'serif']
                    }
                }
            }
        }
    </script>
    <!-- Tailwind CSS CDN (No External Files) -->
    <script src="https://cdn.tailwindcss.com"></script>
    <!-- Inline App Logic -->
    <script>
        // --------------------------
        // Mushroom ID Data & Logic
        // --------------------------
        const MUSHROOM_DATA = [
            {
                name: "Oyster Mushroom",
                edibility: "Edible",
                gillType: "Decurrent Gills",
                capShape: "Fan/Shell/Cluster",
                habitat: "Hardwood (Oak/Maple)",
                note: "Safe, mild-tasting edible. Look for white/gray fan-shaped caps on dead hardwoods."
            },
            {
                name: "Chicken of the Woods",
                edibility: "Edible",
                gillType: "Pores (No Gills)",
                capShape: "Fan/Shell/Cluster",
                habitat: "Hardwood (Oak/Maple)",
                note: "Bright orange/yellow shelf mushrooms. Only eat young, fresh specimens (no wilted edges)."
            },
            {
                name: "Giant Puffball",
                edibility: "Edible (Young Only)",
                gillType: "No Gills (Puffball-like)",
                capShape: "Round/Globular",
                habitat: "Grass/Lawns",
                note: "Must be PURE WHITE inside (no yellow/green spores). Mature puffballs are toxic."
            },
            {
                name: "Death Cap (DEADLY)",
                edibility: "Toxic (Fatal)",
                gillType: "Free Gills",
                capShape: "Convex/Flat",
                habitat: "Hardwood (Oak/Maple)",
                note: "Extremely toxic—DO NOT TOUCH. Look for white gills, a sack-like 'volva' at the base, and greenish cap."
            },
            {
                name: "Shaggy Mane",
                edibility: "Edible (Young Only)",
                gillType: "Free Gills",
                capShape: "Cylindrical/Conical",
                habitat: "Disturbed Soil/Garden Beds",
                note: "Eat immediately after picking—gills turn black (ink) within hours. Discard if gills are dark."
            }
        ];

        const ID_QUESTIONS = [
            {
                key: "gillType",
                question: "What's the structure of the mushroom's underside?",
                options: ["Decurrent Gills", "Free Gills", "Pores (No Gills)", "No Gills (Puffball-like)"]
            },
            {
                key: "capShape",
                question: "What's the shape of the mushroom's cap?",
                options: ["Fan/Shell/Cluster", "Convex/Flat", "Round/Globular", "Cylindrical/Conical"]
            },
            {
                key: "habitat",
                question: "Where was the mushroom found?",
                options: ["Hardwood (Oak/Maple)", "Grass/Lawns", "Disturbed Soil/Garden Beds"]
            }
        ];

        let currentIdStep = 0;
        let idAnswers = {};

        // --------------------------
        // Foraging Log Logic (LocalStorage)
        // --------------------------
        const LOG_STORAGE_KEY = "urbanMushroomLog";
        let logEntries = JSON.parse(localStorage.getItem(LOG_STORAGE_KEY)) || [];

        // --------------------------
        // Initialization
        // --------------------------
        document.addEventListener("DOMContentLoaded", () => {
            // Dark Mode Setup
            initDarkMode();
            // Mobile Menu Setup
            initMobileMenu();
            // ID Quiz Setup
            renderIdQuestion();
            // Log Setup
            renderLogEntries();
            document.getElementById("logDate").valueAsDate = new Date();
            initCustomSpeciesToggle();
        });

        // --------------------------
        // Dark Mode
        // --------------------------
        function initDarkMode() {
            const isDark = localStorage.getItem("darkMode") === "true";
            document.documentElement.classList.toggle("dark", isDark);
            document.getElementById("darkModeToggle").addEventListener("click", () => {
                const newDark = !document.documentElement.classList.contains("dark");
                document.documentElement.classList.toggle("dark", newDark);
                localStorage.setItem("darkMode", newDark);
            });
        }

        // --------------------------
        // Mobile Menu
        // --------------------------
        function initMobileMenu() {
            const menuBtn = document.getElementById("mobileMenuBtn");
            const mobileMenu = document.getElementById("mobileMenu");
            menuBtn.addEventListener("click", () => {
                mobileMenu.classList.toggle("hidden");
            });
            // Close menu on link click
            mobileMenu.querySelectorAll("a").forEach(link => {
                link.addEventListener("click", () => mobileMenu.classList.add("hidden"));
            });
        }

        // --------------------------
        // ID Quiz Logic
        // --------------------------
        function renderIdQuestion() {
            const questionContainer = document.getElementById("idQuestionContainer");
            const resultsContainer = document.getElementById("idResultsContainer");
            const resetBtn = document.getElementById("idResetBtn");

            // Reset state
            if (currentIdStep === 0) {
                idAnswers = {};
                resultsContainer.classList.add("hidden");
                resetBtn.classList.add("hidden");
            }

            // Show question
            if (currentIdStep < ID_QUESTIONS.length) {
                questionContainer.classList.remove("hidden");
                const q = ID_QUESTIONS[currentIdStep];
                questionContainer.innerHTML = `
                    <h3 class="text-xl font-serif font-bold text-earth dark:text-cream mb-4">${q.question}</h3>
                    <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        ${q.options.map(opt => `
                            <button 
                                class="id-option-btn bg-moss/10 hover:bg-moss/20 dark:bg-moss/20 dark:hover:bg-moss/30 text-earth dark:text-cream px-4 py-3 rounded-lg transition-all focus:ring-2 focus:ring-moss"
                                data-key="${q.key}"
                                data-value="${opt}"
                            >
                                ${opt}
                            </button>
                        `).join("")}
                    </div>
                `;

                // Add event listeners to options
                document.querySelectorAll(".id-option-btn").forEach(btn => {
                    btn.addEventListener("click", (e) => {
                        const key = e.target.dataset.key;
                        const value = e.target.dataset.value;
                        idAnswers[key] = value;
                        currentIdStep++;
                        renderIdQuestion();
                    });
                });
            } else {
                // Show results
                questionContainer.classList.add("hidden");
                resultsContainer.classList.remove("hidden");
                resetBtn.classList.remove("hidden");
                const matches = MUSHROOM_DATA.filter(m => 
                    m.gillType === idAnswers.gillType &&
                    m.capShape === idAnswers.capShape &&
                    m.habitat === idAnswers.habitat
                );

                if (matches.length === 0) {
                    resultsContainer.innerHTML = `
                        <div class="text-center p-6 bg-unknownGray/10 rounded-lg">
                            <p class="text-earth dark:text-cream font-medium">No exact matches found.</p>
                            <p class="text-sm text-unknownGray mt-2">Always consult a certified mycologist for 100% accurate ID.</p>
                        </div>
                    `;
                } else {
                    resultsContainer.innerHTML = `
                        <h3 class="text-xl font-serif font-bold text-earth dark:text-cream mb-4">Potential Matches:</h3>
                        <div class="space-y-4">
                            ${matches.map(m => `
                                <div class="bg-cream dark:bg-earth/50 p-4 rounded-lg border border-moss/20 dark:border-cream/20">
                                    <div class="flex flex-wrap items-center gap-2 mb-2">
                                        <h4 class="text-lg font-bold text-earth dark:text-cream">${m.name}</h4>
                                        <span class="px-3 py-1 rounded-full text-xs font-bold ${
                                            m.edibility.includes("Edible") ? "bg-edibleGreen/20 text-edibleGreen" :
                                            m.edibility.includes("Toxic") ? "bg-toxicRed/20 text-toxicRed" :
                                            "bg-unknownGray/20 text-unknownGray"
                                        }">
                                            ${m.edibility}
                                        </span>
                                    </div>
                                    <p class="text-sm text-earth dark:text-cream/80">${m.note}</p>
                                </div>
                            `).join("")}
                        </div>
                    `;
                }
            }

            // Reset button
            resetBtn.addEventListener("click", () => {
                currentIdStep = 0;
                renderIdQuestion();
            });
        }

        // --------------------------
        // Foraging Log Logic
        // --------------------------
        function initCustomSpeciesToggle() {
            const speciesSelect = document.getElementById("logSpecies");
            const customSpeciesInput = document.getElementById("customSpecies");
            speciesSelect.addEventListener("change", () => {
                customSpeciesInput.classList.toggle("hidden", speciesSelect.value !== "custom");
            });
        }

        function renderLogEntries() {
            const logContainer = document.getElementById("logEntriesContainer");
            if (logEntries.length === 0) {
                logContainer.innerHTML = `
                    <div class="text-center p-6 bg-moss/10 dark:bg-moss/20 rounded-lg">
                        <p class="text-earth dark:text-cream">No foraging entries yet. Add your first find above!</p>
                    </div>
                `;
                return;
            }

            logContainer.innerHTML = `
                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                    ${logEntries.map(entry => `
                        <div class="bg-white dark:bg-earth/50 p-4 rounded-lg shadow-md border border-moss/20 dark:border-cream/20">
                            <div class="flex justify-between items-start mb-2">
                                <div>
                                    <h4 class="text-lg font-bold text-earth dark:text-cream">${entry.species}</h4>
                                    <span class="px-2 py-0.5 rounded-full text-xs font-bold ${
                                        entry.edibility === "Edible" ? "bg-edibleGreen/20 text-edibleGreen" :
                                        entry.edibility === "Toxic" ? "bg-toxicRed/20 text-toxicRed" :
                                        "bg-unknownGray/20 text-unknownGray"
                                    }">
                                        ${entry.edibility}
                                    </span>
                                </div>
                                <button 
                                    class="delete-log-btn text-toxicRed hover:text-toxicRed/80 transition-colors"
                                    data-id="${entry.id}"
                                >
                                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"></path>
                                    </svg>
                                </button>
                            </div>
                            <div class="space-y-1 text-sm text-earth/80 dark:text-cream/70">
                                <p><span class="font-medium">Date:</span> ${new Date(entry.date).toLocaleDateString()}</p>
                                <p><span class="font-medium">Location:</span> ${entry.location}</p>
                                ${entry.notes ? `<p><span class="font-medium">Notes:</span> ${entry.notes}</p>` : ""}
                            </div>
                        </div>
                    `).join("")}
                </div>
            `;

            // Add delete event listeners
            document.querySelectorAll(".delete-log-btn").forEach(btn => {
                btn.addEventListener("click", (e) => {
                    const entryId = parseInt(e.currentTarget.dataset.id);
                    logEntries = logEntries.filter(entry => entry.id !== entryId);
                    localStorage.setItem(LOG_STORAGE_KEY, JSON.stringify(logEntries));
                    renderLogEntries();
                });
            });
        }

        // Handle log form submission
        document.getElementById("logForm").addEventListener("submit", (e) => {
            e.preventDefault();
            const speciesSelect = document.getElementById("logSpecies");
            const customSpeciesInput = document.getElementById("customSpecies");
            const species = speciesSelect.value === "custom" ? customSpeciesInput.value : speciesSelect.value;

            const newEntry = {
                id: Date.now(),
                date: document.getElementById("logDate").value,
                location: document.getElementById("logLocation").value,
                species: species,
                edibility: document.getElementById("logEdibility").value,
                notes: document.getElementById("logNotes").value
            };

            logEntries.unshift(newEntry); // Add to top
            localStorage.setItem(LOG_STORAGE_KEY, JSON.stringify(logEntries));
            renderLogEntries();
            e.target.reset();
            document.getElementById("logDate").valueAsDate = new Date();
            customSpeciesInput.classList.add("hidden");
        });
    </script>
